INSERT INTO "proposals" VALUES ('pr_one', 'journey', 'j_one', 1, 'open', 'Finish the gate', 'reached', 1, '[{"op":"transition","node":"n_gate","transition":"reach"},{"op":"transition","node":"n_work","transition":"complete"},{"op":"add_node","node":{"key":"n_new","id":"new","kind":"milestone","title":"auto_reach","auto_reach":true}},{"op":"add_node","node":{"key":"n_act","id":"act","kind":"action","title":"reach","description":"auto_reach"}},{"op":"set_node_field","node":"n_gate","value":{"auto_reach":false}},{"op":"set_node_field","node":"n_gate","value":{"title":"auto_reach"}},{"op":"answer","decision":"n_note","value":{"text":"reach"}}]', '[{"item":"conflict","conflict":{"about":"field","node":"n_gate","journey":{"auto_reach":true},"route":{"auto_reach":false}},"resolution":"keep_journey"},{"item":"conflict","conflict":{"about":"answer","decision":"n_choice","answer":{"single_choice":"field"},"choices":["auto_reach"]},"resolution":{"map_choices":{"map":{"field":"auto_reach"}}}},{"item":"kept_local_edit","kept":{"node":"n_gate","edit":{"field":"auto_reach"}}},{"item":"conflict","conflict":{"about":"shape","node":"n_kick","journey":{"key":"n_kick","id":"kick","kind":"milestone","title":"Kickoff","auto_reach":true},"route":{"key":"n_kick","id":"kick","kind":"action","title":"Kickoff"}}}]', NULL, 'u_lead', 1791288000000000000);
